import type { StorageService } from '../../services/storage.ts';

export interface PhotoObjectKeys {
  readonly originalKey: string;
  readonly displayKey: string;
  readonly thumbKey: string;
}

export type OriginalExtension = 'jpg' | 'png' | 'webp';

/**
 * Storage keys are generated by the server, never from the uploaded filename.
 * The id is created before the upload so all three keys share one prefix.
 */
export function buildPhotoObjectKeys(
  circleId: string,
  photoId: string,
  extension: OriginalExtension,
): PhotoObjectKeys {
  const base = `circles/${circleId}/photos/${photoId}`;

  return {
    originalKey: `${base}/original.${extension}`,
    displayKey: `${base}/display.webp`,
    thumbKey: `${base}/thumb.webp`,
  };
}

/** Every object a persisted photo owns. */
export function photoObjectKeys(photo: PhotoObjectKeys): string[] {
  return [photo.originalKey, photo.displayKey, photo.thumbKey];
}

/** Maximum concurrent storage deletes when emptying a large album. */
export const DELETE_OBJECTS_CONCURRENCY = 8;

export interface DeleteObjectsResult {
  readonly total: number;
  readonly failures: number;
}

/**
 * Best-effort cleanup used after a failed upload or when emptying an album.
 *
 * Deletes run through a small pool so a 500-photo album does not open 1,500
 * S3 requests at once. `allSettled` semantics guarantee one missing object
 * cannot stop the rest, and the caller keeps its original error instead of
 * masking it with a cleanup failure.
 */
export async function deleteObjects(
  storage: StorageService,
  keys: readonly string[],
): Promise<DeleteObjectsResult> {
  let nextIndex = 0;
  let failures = 0;

  const worker = async (): Promise<void> => {
    while (nextIndex < keys.length) {
      const index = nextIndex;
      nextIndex += 1;
      const key = keys[index];

      if (key === undefined) {
        continue;
      }

      try {
        await storage.delete(key);
      } catch {
        failures += 1;
      }
    }
  };

  const workers = Array.from({ length: Math.min(DELETE_OBJECTS_CONCURRENCY, keys.length) }, () =>
    worker(),
  );

  await Promise.all(workers);

  return { total: keys.length, failures };
}
